using Npgsql; var builder = WebApplication.CreateBuilder(args); builder.Services.AddHttpClient(); var app = builder.Build(); var cs = Environment.GetEnvironmentVariable("DB_CONNECTION") ?? "Host=db;Port=5432;Database=library_db;Username=postgres;Password=password123"; var cu = Environment.GetEnvironmentVariable("CATALOG_URL") ?? "http://catalog-service:8080"; await using (var c = new NpgsqlConnection(cs)) { await c.OpenAsync(); await new NpgsqlCommand("CREATE TABLE IF NOT EXISTS loans(id SERIAL PRIMARY KEY,book_id INT NOT NULL,reader_name TEXT NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT NOW());", c).ExecuteNonQueryAsync(); } app.MapGet("/loans", async () => { var l = new List<object>(); await using var c = new NpgsqlConnection(cs); await c.OpenAsync(); await using var r = await new NpgsqlCommand("SELECT id,book_id,reader_name,created_at FROM loans ORDER BY id", c).ExecuteReaderAsync(); while (await r.ReadAsync()) l.Add(new { Id = r.GetInt32(0), BookId = r.GetInt32(1), ReaderName = r.GetString(2), CreatedAt = r.GetDateTime(3) }); return Results.Ok(l); }); app.MapPost("/loans", async (LoanDto d, IHttpClientFactory hf) => { var res = await hf.CreateClient().PostAsync($"{cu}/books/{d.BookId}/reserve", null); if (!res.IsSuccessStatusCode) return Results.BadRequest(new { Error = "Book unavailable" }); await using var c = new NpgsqlConnection(cs); await c.OpenAsync(); var cmd = new NpgsqlCommand("INSERT INTO loans(book_id,reader_name)VALUES(@b,@r)RETURNING id", c); cmd.Parameters.AddWithValue("b", d.BookId); cmd.Parameters.AddWithValue("r", d.ReaderName); var id = (int)(await cmd.ExecuteScalarAsync())!; return Results.Created($"/loans/{id}", new { Id = id, d.BookId, d.ReaderName, Status = "Issued" }); }); app.Run(); record LoanDto(int BookId, string ReaderName);
